1	package indexroom
2	
3	import (
4		"crypto/hmac"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/base64"
8		"encoding/binary"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"sort"
14		"strings"
15		"sync/atomic"
16	)
17	
18	// ErrInvalidArgument marks a rejected query: out-of-range heights or page
19	// size, a malformed cursor, a cursor issued by another index instance, or
20	// continuation conditions that differ from the first page. It never reports
21	// chain data problems; use errors.Is to tell it apart from ErrQueryChanged.
22	var ErrInvalidArgument = errors.New("indexroom: invalid query argument")
23	
24	// ErrQueryChanged marks a continuation whose pinned range no longer matches
25	// the first page: a block in the range was replaced (even under the same
26	// hash, and even if only its timestamp changed) or the chain was shortened
27	// below the pinned upper bound. No results are returned; the caller must
28	// restart from a first-page query.
29	var ErrQueryChanged = errors.New("indexroom: query data changed")
30	
31	// queryTxsHookLocked is a test-only rendezvous invoked once per QueryTxs
32	// call while index.mu is held: for a first page after the tip-bound height has
33	// been resolved (and non-empty ranges only), and for a continuation only after
34	// every pinned-range check has passed, so the call is committed to a
35	// successful page against the chain state in effect. It is nil in production;
36	// reorg regression tests park a query here to force a concurrent Reorg to wait
37	// (or park the Reorg and make the query wait), making the "one complete
38	// main-chain view per page" observation deterministic instead of relying on
39	// scheduling luck.
40	var queryTxsHookLocked func(from, to int64, continuation bool)
41	
42	const (
43		// DefaultPageSize is the page length when TxQuery.PageSize is zero.
44		DefaultPageSize = 100
45		// MaxPageSize is the largest accepted TxQuery.PageSize.
46		MaxPageSize = 1000
47	)
48	
49	// TxQuery describes a transaction lookup against the main chain.
50	type TxQuery struct {
51		// From and To bound the searched heights, both inclusive. A zero From
52		// starts at height 1. A zero To pins the chain tip seen by the first
53		// page; an explicit To above the tip is clamped to it. Explicit heights
54		// must be positive, and an explicit To must not be below From.
55		From int64
56		To   int64
57		// TxIDs restricts results to these identifiers, matched by exact string
58		// comparison; an empty slice disables the filter. Duplicates and order
59		// inside the slice are irrelevant.
60		TxIDs []string
61		// PageSize picks the page length, 1..MaxPageSize; zero means
62		// DefaultPageSize. It may change between pages of the same query.
63		PageSize int
64		// Cursor continues an earlier query; empty asks for the first page. On
65		// continuation the height range and TxIDs must equal the first page's.
66		Cursor string
67	}
68	
69	// TxHit is one transaction occurrence on the main chain. The same
70	// identifier appears once per occurrence, in different blocks or several
71	// times inside one block.
72	type TxHit struct {
73		Height    int64
74		BlockHash string
75		TxID      string
76		Position  int
77	}
78	
79	// TxPage is one page of query results together with statistics over the
80	// whole filtered range. Hits are ordered by height, then by position inside
81	// the block.
82	type TxPage struct {
83		Hits []TxHit
84		// TotalMatches counts every matching occurrence in the pinned range; it
85		// does not change between pages of the same query.
86		TotalMatches int64
87		// MatchedBlocks counts the blocks holding at least one match.
88		MatchedBlocks int64
89		// ToHeight is the upper bound pinned by the first page: the requested
90		// To clamped to the chain tip seen at that moment.
91		ToHeight int64
92		// NextCursor continues the query; empty means this is the last page.
93		NextCursor string
94	}
95	
96	// QueryTxs searches the main chain for transaction occurrences matching the
97	// query. Every call observes one complete chain state: concurrent Append or
98	// Reorg calls never leak into a page, and the returned records are copies
99	// the caller may freely mutate. The query itself never modifies the index.
100	//
101	// The first page (empty Cursor) pins the filtered range and returns a
102	// continuation cursor while more results remain. Continuations reuse the
103	// pinned range — blocks appended above it are invisible to the query — and
104	// succeed as long as every block inside the range still matches the first
105	// page; otherwise they fail with ErrQueryChanged.
106	func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
107		pageSize, err := normalizePageSize(query.PageSize)
108		if err != nil {
109			return TxPage{}, err
110		}
111		if query.Cursor != "" {
112			return index.continueQuery(query, pageSize)
113		}
114		return index.firstQuery(query, pageSize)
115	}
116	
117	func normalizePageSize(size int) (int, error) {
118		if size == 0 {
119			return DefaultPageSize, nil
120		}
121		if size < 0 || size > MaxPageSize {
122			return 0, fmt.Errorf("%w: page size must be between 1 and %d", ErrInvalidArgument, MaxPageSize)
123		}
124		return size, nil
125	}
126	
127	// normalizeRange validates the requested heights and resolves the zero From
128	// default. A zero To is left as-is; it is resolved against the chain tip
129	// while holding the lock.
130	func normalizeRange(from, to int64) (int64, int64, error) {
131		if from < 0 {
132			return 0, 0, fmt.Errorf("%w: from height must be positive", ErrInvalidArgument)
133		}
134		if to < 0 {
135			return 0, 0, fmt.Errorf("%w: to height must be positive", ErrInvalidArgument)
136		}
137		if from == 0 {
138			from = 1
139		}
140		if to != 0 && to < from {
141			return 0, 0, fmt.Errorf("%w: to height is below from height", ErrInvalidArgument)
142		}
143		return from, to, nil
144	}
145	
146	func (index *Index) firstQuery(query TxQuery, pageSize int) (TxPage, error) {
147		from, to, err := normalizeRange(query.From, query.To)
148		if err != nil {
149			return TxPage{}, err
150		}
151	
152		index.mu.Lock()
153		defer index.mu.Unlock()
154	
155		if to == 0 || to > index.Tip {
156			to = index.Tip
157		}
158		page := TxPage{Hits: []TxHit{}, ToHeight: to}
159		if from > to {
160			// Empty index or a start above the tip: a successful empty result.
161			return page, nil
162		}
163		if queryTxsHookLocked != nil {
164			queryTxsHookLocked(from, to, false)
165		}
166		hits, blocks := index.collectLocked(from, to, query.TxIDs)
167		return index.makePageLocked(query, from, to, hits, blocks, 0, pageSize), nil
168	}
169	
170	func (index *Index) continueQuery(query TxQuery, pageSize int) (TxPage, error) {
171		payload, err := index.decodeCursor(query.Cursor)
172		if err != nil {
173			return TxPage{}, err
174		}
175		from, _, err := normalizeRange(query.From, query.To)
176		if err != nil {
177			return TxPage{}, err
178		}
179		if from != payload.From {
180			return TxPage{}, fmt.Errorf("%w: from height differs from the first page", ErrInvalidArgument)
181		}
182		if query.To != payload.ReqTo {
183			return TxPage{}, fmt.Errorf("%w: to height differs from the first page", ErrInvalidArgument)
184		}
185		if got := hex.EncodeToString(hashTxSet(query.TxIDs)); got != payload.Set {
186			return TxPage{}, fmt.Errorf("%w: transaction filter differs from the first page", ErrInvalidArgument)
187		}
188	
189		index.mu.Lock()
190		defer index.mu.Unlock()
191	
192		if index.Tip < payload.To {
193			return TxPage{}, fmt.Errorf("%w: chain tip %d is below the pinned upper bound %d",
194				ErrQueryChanged, index.Tip, payload.To)
195		}
196		if got := hex.EncodeToString(index.fingerprintLocked(payload.From, payload.To)); got != payload.FP {
197			return TxPage{}, fmt.Errorf("%w: blocks in the pinned range differ from the first page", ErrQueryChanged)
198		}
199		if queryTxsHookLocked != nil {
200			queryTxsHookLocked(payload.From, payload.To, true)
201		}
202		hits, blocks := index.collectLocked(payload.From, payload.To, query.TxIDs)
203		if payload.Off > int64(len(hits)) {
204			return TxPage{}, fmt.Errorf("%w: cursor offset is beyond the pinned results", ErrQueryChanged)
205		}
206		return index.makePageLocked(query, payload.From, payload.To, hits, blocks, payload.Off, pageSize), nil
207	}
208	
209	// makePageLocked slices one page out of the full match list and mints the
210	// continuation cursor when matches remain. The caller must hold index.mu.
211	func (index *Index) makePageLocked(query TxQuery, from, to int64, hits []TxHit, blocks int64, offset int64, pageSize int) TxPage {
212		page := TxPage{
213			TotalMatches:  int64(len(hits)),
214			MatchedBlocks: blocks,
215			ToHeight:      to,
216		}
217		rest := hits[int(offset):]
218		end := pageSize
219		if end > len(rest) {
220			end = len(rest)
221		}
222		page.Hits = append([]TxHit{}, rest[:end]...)
223		if end < len(rest) {
224			page.NextCursor = index.encodeCursor(cursorPayload{
225				V:     1,
226				From:  from,
227				ReqTo: query.To,
228				To:    to,
229				Set:   hex.EncodeToString(hashTxSet(query.TxIDs)),
230				FP:    hex.EncodeToString(index.fingerprintLocked(from, to)),
231				Off:   offset + int64(end),
232			})
233		}
234		return page
235	}
236	
237	// collectLocked gathers every matching occurrence in [from, to], ordered by
238	// height and position, plus the number of blocks holding at least one match.
239	// The caller must hold index.mu.
240	func (index *Index) collectLocked(from, to int64, txIDs []string) (hits []TxHit, blocks int64) {
241		var filter map[string]struct{}
242		if len(txIDs) > 0 {
243			filter = make(map[string]struct{}, len(txIDs))
244			for _, id := range txIDs {
245				filter[id] = struct{}{}
246			}
247		}
248		hits = []TxHit{}
249		for height := from; height <= to; height++ {
250			block := index.Blocks[height]
251			matched := false
252			for position, tx := range block.Txs {
253				if filter != nil {
254					if _, ok := filter[tx]; !ok {
255						continue
256					}
257				}
258				hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
259				matched = true
260			}
261			if matched {
262				blocks++
263			}
264		}
265		return hits, blocks
266	}
267	
268	// fingerprintLocked hashes the exact content of every block in [from, to]:
269	// height, hash, parent, the ordered transaction list, and the timestamp
270	// (distinguishing a missing timestamp from zero). The caller must hold
271	// index.mu.
272	func (index *Index) fingerprintLocked(from, to int64) []byte {
273		h := sha256.New()
274		var lenBuf [8]byte
275		writeString := func(s string) {
276			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(s)))
277			h.Write(lenBuf[:])
278			h.Write([]byte(s))
279		}
280		for height := from; height <= to; height++ {
281			block := index.Blocks[height]
282			binary.BigEndian.PutUint64(lenBuf[:], uint64(block.Height))
283			h.Write(lenBuf[:])
284			writeString(block.Hash)
285			writeString(block.Parent)
286			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(block.Txs)))
287			h.Write(lenBuf[:])
288			for _, tx := range block.Txs {
289				writeString(tx)
290			}
291			if block.Time == nil {
292				h.Write([]byte{0})
293			} else {
294				h.Write([]byte{1})
295				binary.BigEndian.PutUint64(lenBuf[:], uint64(*block.Time))
296				h.Write(lenBuf[:])
297			}
298		}
299		return h.Sum(nil)
300	}
301	
302	// hashTxSet hashes the deduplicated, sorted identifier set so that cursor
303	// validation is insensitive to duplicates and ordering.
304	func hashTxSet(txIDs []string) []byte {
305		unique := make(map[string]struct{}, len(txIDs))
306		sorted := make([]string, 0, len(txIDs))
307		for _, id := range txIDs {
308			if _, ok := unique[id]; ok {
309				continue
310			}
311			unique[id] = struct{}{}
312			sorted = append(sorted, id)
313		}
314		sort.Strings(sorted)
315		h := sha256.New()
316		var lenBuf [8]byte
317		for _, id := range sorted {
318			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(id)))
319			h.Write(lenBuf[:])
320			h.Write([]byte(id))
321		}
322		return h.Sum(nil)
323	}
324	
325	// cursorPayload is the signed state carried between pages of one query.
326	type cursorPayload struct {
327		V     int    `json:"v"`
328		From  int64  `json:"from"`
329		ReqTo int64  `json:"reqTo"`
330		To    int64  `json:"to"`
331		Set   string `json:"set"`
332		FP    string `json:"fp"`
333		Off   int64  `json:"off"`
334	}
335	
336	const cursorPrefix = "q1"
337	
338	// encodeCursor serializes the payload and signs it with the per-instance
339	// key, so cursors are self-contained yet unusable on any other index.
340	func (index *Index) encodeCursor(payload cursorPayload) string {
341		raw, err := json.Marshal(payload)
342		if err != nil {
343			panic(err) // cursorPayload only contains marshalable fields
344		}
345		body := base64.RawURLEncoding.EncodeToString(raw)
346		mac := hmac.New(sha256.New, index.key[:])
347		mac.Write([]byte(cursorPrefix + "." + body))
348		sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
349		return cursorPrefix + "." + body + "." + sig
350	}
351	
352	// decodeCursor verifies the signature before trusting any payload field;
353	// every failure is an argument error, never a data-changed error.
354	func (index *Index) decodeCursor(cursor string) (cursorPayload, error) {
355		var payload cursorPayload
356		parts := strings.Split(cursor, ".")
357		if len(parts) != 3 || parts[0] != cursorPrefix {
358			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
359		}
360		sig, err := base64.RawURLEncoding.DecodeString(parts[2])
361		if err != nil {
362			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
363		}
364		mac := hmac.New(sha256.New, index.key[:])
365		mac.Write([]byte(parts[0] + "." + parts[1]))
366		if !hmac.Equal(sig, mac.Sum(nil)) {
367			return payload, fmt.Errorf("%w: cursor not recognized by this index", ErrInvalidArgument)
368		}
369		raw, err := base64.RawURLEncoding.DecodeString(parts[1])
370		if err != nil {
371			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
372		}
373		if err := json.Unmarshal(raw, &payload); err != nil || payload.V != 1 {
374			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
375		}
376		return payload, nil
377	}
378	
379	var keyFallback atomic.Uint64
380	
381	// newKey derives the per-instance cursor signing key. crypto/rand is not
382	// expected to fail; the counter fallback still keeps keys unique per
383	// instance so cursors never validate across indexes.
384	func newKey() [32]byte {
385		var key [32]byte
386		if _, err := rand.Read(key[:]); err != nil {
387			binary.BigEndian.PutUint64(key[:8], keyFallback.Add(1))
388		}
389		return key
390	}
