12	// This file guards QueryTimeStats against a snapshot Restore that replaces
13	// the whole main chain. While the snapshot is still being read the index
14	// stays queryable and every stats query must answer from the complete old
15	// chain. Once a valid snapshot has been applied, every new query must answer
16	// from the complete new chain: no transaction, missing-time count, or height
17	// bound of the replaced chain may linger. A query racing the replacement
18	// itself may land on either side, but every field of ONE returned TimeStats —
19	// per-bucket counts, whole-window totals, the resolved height range, and the
20	// missing-time-block count — must come from that same complete chain. And a
21	// snapshot whose invalidity (a negative timestamp) only surfaces in its very
22	// last block must leave the old chain bit-for-bit in effect.
23	//
24	// The scenario (window [0,30), step 10 -> [0,10) [10,20) [20,30); height
25	// bounds left at zero so the range starts at height 1 and pins the observed
26	// chain tip; no transaction filter):
27	//
28	//	Old main chain, tip 4:
29	//	  h1 t=0  txs [a, a]  // same id twice in one block/segment
30	//	  h2 t=10 txs [a, b]  // a crosses segments (also in h1)
31	//	  h3 t=-  txs [a]     // missing timestamp: enters no segment and no block
32	//	  h4 t=20 txs [c]
33	//	Version-2 snapshot replacing it, tip 2:
34	//	  j1 t=0  txs [b]
35	//	  j2 t=20 txs [b, d, d] // d twice in one block: two occurrences, one id
36	//
37	// Old-chain result (range 1..4, one missing-time block):
38	//
39	//	[0,10):  occ 2 (a,a), distinct {a}=1,   blocks 1
40	//	[10,20): occ 2 (a,b), distinct {a,b}=2, blocks 1
41	//	[20,30): occ 1 (c),   distinct {c}=1,   blocks 1
42	//	totals: occ 5, window-distinct {a,b,c}=3, blocks 3, missing 1, to 4
43	//
44	// New-chain result (range 1..2, no missing-time block, [10,20) stays zeroed):
45	//
46	//	[0,10):  occ 1 (b),     distinct {b}=1,   blocks 1
47	//	[10,20): occ 0,         distinct 0,       blocks 0
48	//	[20,30): occ 3 (b,d,d), distinct {b,d}=2, blocks 1
49	//	totals: occ 4, window-distinct {b,d}=2, blocks 2, missing 0, to 2
50	//
51	// The two complete answers differ in every discriminating field, so any
52	// stitched-together answer — old transaction counts under the new height
53	// bound, the old missing-time count on the new chain, a dedup result from
54	// the wrong chain — stands out.
55	
56	var restoreStatsQuery = TimeStatsQuery{Start: 0, End: 30, StepSeconds: 10}
