67	func restoreNewChainBlocks() []Block {
68		return []Block{
69			timeBlock(1, "j1", "g", []string{"b"}, intptr(0)),
70			timeBlock(2, "j2", "j1", []string{"b", "d", "d"}, intptr(20)),
71		}
72	}
