75	const restoreNewSnapshot = `{"version":2,"tip":2,"blocks":[` +
76		`{"height":1,"hash":"j1","parent":"g","txs":["b"],"timestamp":0},` +
77		`{"height":2,"hash":"j2","parent":"j1","txs":["b","d","d"],"timestamp":20}` +
78		`]}`
