217	// gatedReader delivers the first prefix bytes of data, then parks until
218	// release is closed, then delivers the rest. It lets a test hold Restore
219	// mid-parse — after whole blocks have already been consumed but before the
220	// replacement is applied — without any sleeps or scheduling luck.
221	type gatedReader struct {
222		data    []byte
223		prefix  int
224		off     int
225		entered chan struct{}
226		release chan struct{}
227		once    sync.Once
228	}
229	
230	func newGatedReader(t *testing.T, data, cutMarker string) *gatedReader {
231		t.Helper()
232		prefix := strings.Index(data, cutMarker)
233		if prefix <= 0 {
234			t.Fatalf("test setup: cut marker %q not found in %q", cutMarker, data)
235		}
236		return &gatedReader{
237			data:    []byte(data),
238			prefix:  prefix,
239			entered: make(chan struct{}),
240			release: make(chan struct{}),
241		}
242	}
243	
244	func (r *gatedReader) Read(p []byte) (int, error) {
245		if r.off < r.prefix {
246			n := copy(p, r.data[r.off:r.prefix])
247			r.off += n
248			return n, nil
249		}
250		r.once.Do(func() { close(r.entered) })
251		<-r.release
252		if r.off >= len(r.data) {
253			return 0, io.EOF
254		}
255		n := copy(p, r.data[r.off:])
256		r.off += n
257		return n, nil
258	}
