302	// A query that has pinned the OLD tip (4) and still holds the lock when the
303	// restore's replacement is ready must finish on the complete old chain; the
304	// restore applies only afterwards.
305	func TestQueryTimeStatsInFlightObservesCompleteOldChainBeforeRestore(t *testing.T) {
306		index := buildRestoreOldChain(t)
307	
308		queryParked := make(chan struct{})
309		releaseQuery := make(chan struct{})
310		var hookOnce sync.Once
311		statsQueryHookLocked = func(to int64) {
312			if to != 4 {
313				t.Errorf("stats hook resolved to=%d, want old tip 4", to)
314			}
315			hookOnce.Do(func() { close(queryParked) })
316			<-releaseQuery
317		}
318		t.Cleanup(func() { statsQueryHookLocked = nil })
319	
320		result := make(chan TimeStats, 1)
321		errCh := make(chan error, 1)
322		go func() {
323			stats, err := index.QueryTimeStats(restoreStatsQuery)
324			if err != nil {
325				errCh <- err
326				return
327			}
328			result <- stats
329		}()
330		<-queryParked // query holds index.mu and has pinned tip 4
331	
332		restoreDone := make(chan error, 1)
333		go func() {
334			// strings.Reader is fully readable, so this restore parses the whole
335			// snapshot and then blocks on index.mu behind the parked query.
336			restoreDone <- index.Restore(strings.NewReader(restoreNewSnapshot))
337		}()
338	
339		close(releaseQuery) // the query scans and finishes on the old chain first
340		var got TimeStats
341		select {
342		case got = <-result:
343		case err := <-errCh:
344			t.Fatalf("concurrent query failed: %v", err)
345		}
346		if !reflect.DeepEqual(got, literalRestoreOldStats()) {
347			t.Fatalf("query holding the lock across restore commit must see the old chain:\n%+v", got)
348		}
349		if err := classifyTimeStats(got, literalRestoreOldStats(), literalRestoreNewStats()); err != nil {
350			t.Fatalf("in-flight query did not return one complete chain:\n%v", err)
351		}
352		statsQueryHookLocked = nil // the rendezvous is spent; later queries run free
353		if err := <-restoreDone; err != nil {
354			t.Fatalf("restore failed: %v", err)
355		}
356		stats, err := index.QueryTimeStats(restoreStatsQuery)
357		if err != nil {
358			t.Fatal(err)
359		}
360		if !reflect.DeepEqual(stats, literalRestoreNewStats()) {
361			t.Fatalf("query after restore must see the complete new chain:\n%+v", stats)
362		}
363	}
