488		// Old transaction counts and dedup under the NEW upper height.
489		mixed := oldRef
490		mixed.ToHeight = newRef.ToHeight
491		if err := classifyTimeStats(mixed, oldRef, newRef); err == nil {
492			t.Fatal("old counts under the new tip height were accepted")
493		} else if !strings.Contains(err.Error(), "MIXED") {
494			t.Fatalf("old-counts/new-height mixture not reported as MIXED:\n%v", err)
495		}
