528		const readers = 4
529		const reads = 80
530	
531		stop := make(chan struct{})
532		var wg sync.WaitGroup
533		for r := 0; r < restorers; r++ {
534			wg.Add(1)
535			go func(seed int) {
536				defer wg.Done()
537				for i := 0; i < rounds; i++ {
538					select {
539					case <-stop:
540						return
541					default:
542					}
543					snapshot := restoreNewSnapshot
544					if (i+seed)%2 == 0 {
545						snapshot = oldSnapshot
546					}
547					if err := index.Restore(strings.NewReader(snapshot)); err != nil {
548						t.Errorf("restore failed: %v", err)
549						return
550					}
551				}
552			}(r)
553		}
554		for r := 0; r < readers; r++ {
555			wg.Add(1)
556			go func() {
557				defer wg.Done()
558				for i := 0; i < reads; i++ {
559					select {
560					case <-stop:
561						return
562					default:
563					}
564					stats, err := index.QueryTimeStats(restoreStatsQuery)
565					if err != nil {
566						t.Errorf("query failed: %v", err)
567						return
568					}
569					if err := classifyTimeStats(stats, oldRef, newRef); err != nil {
570						t.Errorf("%v", err)
571						return
572					}
573				}
574			}()
575		}
576		wg.Wait()
577		close(stop)
