77	func buildQueryOldChain(t *testing.T) *Index {
78		t.Helper()
79		index := New()
80		for _, b := range queryOldChainBlocks() {
81			if err := index.Append(b); err != nil {
82				t.Fatalf("setup append at %d: %v", b.Height, err)
