88	// referenceTxHits is an independent oracle: it derives the complete ordered
89	// occurrence list from an explicitly supplied chain, not from the Index under
90	// test, so a shared QueryTxs bug cannot make an expectation match itself.
91	func referenceTxHits(chain []Block) []TxHit {
92		hits := []TxHit{}
93		for _, block := range chain {
94			for position, tx := range block.Txs {
95				hits = append(hits, TxHit{
96					Height:    block.Height,
97					BlockHash: block.Hash,
98					TxID:      tx,
99					Position:  position,
100				})
101			}
102		}
103		return hits
104	}
105	
106	func referenceMatchedBlocks(chain []Block) int64 {
107		var blocks int64
108		for _, block := range chain {
109			if len(block.Txs) > 0 {
110				blocks++
111			}
112		}
113		return blocks
114	}
115	
116	// referenceTxPage is one page of the complete answer for chain (heights
117	// 1..len(chain)) sliced at offset, with the whole-range statistics the page
118	// must carry. The continuation cursor is deliberately excluded: it is opaque
119	// and is validated separately by actually following it.
120	func referenceTxPage(chain []Block, pageSize int, offset int64) TxPage {
121		full := referenceTxHits(chain)
122		rest := full[offset:]
123		end := pageSize
124		if end > len(rest) {
125			end = len(rest)
126		}
127		return TxPage{
128			Hits:          append([]TxHit{}, rest[:end]...),
129			TotalMatches:  int64(len(full)),
130			MatchedBlocks: referenceMatchedBlocks(chain),
131			ToHeight:      int64(len(chain)),
132		}
133	}
