135	// Hand-derived key records, so the guarantee rests on the literal
136	// transactions of each branch rather than on oracle-vs-DeepEqual alone.
137	func literalOldFirstPage() TxPage {
138		return TxPage{
139			Hits: []TxHit{
140				{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
141				{Height: 1, BlockHash: "h1", TxID: "x", Position: 1},
142				{Height: 2, BlockHash: "h2", TxID: "y", Position: 0},
143			},
144			TotalMatches:  10,
145			MatchedBlocks: 5,
146			ToHeight:      5,
147		}
148	}
149	
150	func literalNewFirstPage() TxPage {
151		page := literalOldFirstPage()
152		page.TotalMatches = 8
153		page.MatchedBlocks = 4
154		page.ToHeight = 4
155		return page
156	}
