11	// statsQueryHookLocked is a test-only rendezvous invoked once per
12	// QueryTimeStats call while index.mu is held, with the resolved tip-bound
13	// height (after clamping, before any block is scanned). It is nil in
14	// production; reorg regression tests set it to park a query that has already
15	// pinned its height range with the lock held, forcing a concurrent Reorg to
16	// wait and making the "one complete main-chain state" observation
17	// deterministic instead of relying on scheduling luck.
18	var statsQueryHookLocked func(resolvedTo int64)
19	
20	// TimeStatsQuery asks for transaction statistics over a half-open time
21	// window, segmented into fixed-length buckets.
22	//
23	// From and To reuse the TxQuery height semantics: heights are inclusive, a
24	// zero From starts at height 1, a zero To pins the chain tip, and an
25	// explicit To above the tip is clamped to it. TxIDs reuses the exact-string
26	// filter semantics, including duplicates and empty identifiers.
27	//
28	// Start and End are Unix seconds bounding the window [Start, End): Start is
29	// included, End is excluded. Both must be non-negative and Start must be
30	// below End. StepSeconds is the bucket length in seconds and must be
31	// positive; buckets start at Start and the final bucket is cut off at End.
32	// Times outside any int64 range cannot be requested.
33	type TimeStatsQuery struct {
34		From        int64
35		To          int64
36		TxIDs       []string
37		Start       int64
38		End         int64
39		StepSeconds int64
40	}
41	
42	// TimeBucket is statistics for one half-open segment [Start, End). Buckets
43	// with no matching transactions are returned with every count at zero.
44	type TimeBucket struct {
45		Start int64
46		End   int64
47		// TxCount counts matching transaction occurrences in the segment.
48		TxCount int64
49		// DistinctTxIDs counts the different matching identifiers in the segment.
50		DistinctTxIDs int64
51		// Blocks counts blocks whose timestamp falls in the segment and which
52		// hold at least one matching transaction.
53		Blocks int64
54	}
55	
56	// TimeTotals summarizes the whole window with the same counters as a bucket.
57	// DistinctTxIDs is deduplicated over the whole window, not summed from the
58	// per-bucket values.
59	type TimeTotals struct {
60		TxCount       int64
61		DistinctTxIDs int64
62		Blocks        int64
63	}
64	
65	// TimeStats is the result of QueryTimeStats. Buckets are ordered by ascending
66	// time and always cover the whole requested window, even on an empty chain,
67	// above the chain tip, or when nothing matches. MissingTimeBlocks reports how
68	// many blocks in the resolved height range carry no timestamp; those blocks
69	// never enter a bucket, and the count ignores the transaction filter.
70	type TimeStats struct {
71		Buckets []TimeBucket
72		Totals  TimeTotals
73		// FromHeight and ToHeight are the resolved inclusive height bounds,
74		// clamped to the chain tip observed by this call.
75		FromHeight int64
76		ToHeight   int64
77		// MissingTimeBlocks counts blocks in [FromHeight, ToHeight] without a
78		// timestamp, regardless of the transaction filter.
79		MissingTimeBlocks int64
80	}
81	
82	// QueryTimeStats buckets matching transactions by block timestamp over the
83	// requested height range. The call observes one complete main-chain state:
84	// concurrent Append, Reorg, or Restore calls never mix old and new blocks
85	// into the answer, and the index is never modified.
86	func (index *Index) QueryTimeStats(query TimeStatsQuery) (TimeStats, error) {
87		from, to, err := normalizeRange(query.From, query.To)
88		if err != nil {
89			return TimeStats{}, err
90		}
91		if query.Start < 0 {
92			return TimeStats{}, fmt.Errorf("%w: start time must not be negative", ErrInvalidArgument)
93		}
94		if query.End < 0 {
95			return TimeStats{}, fmt.Errorf("%w: end time must not be negative", ErrInvalidArgument)
96		}
97		if query.Start >= query.End {
98			return TimeStats{}, fmt.Errorf("%w: start time must be below end time", ErrInvalidArgument)
99		}
100		if query.StepSeconds <= 0 {
101			return TimeStats{}, fmt.Errorf("%w: step seconds must be positive", ErrInvalidArgument)
102		}
103	
104		// Window length is positive and bounded by MaxInt64 since End > Start.
105		width := query.End - query.Start
106		count := width / query.StepSeconds
107		if width%query.StepSeconds != 0 {
108			count++
109		}
110		if count > MaxTimeBuckets {
111			return TimeStats{}, fmt.Errorf("%w: time window would produce %d buckets, limit is %d",
112				ErrInvalidArgument, count, MaxTimeBuckets)
113		}
114	
115		var filter map[string]struct{}
116		if len(query.TxIDs) > 0 {
117			filter = make(map[string]struct{}, len(query.TxIDs))
118			for _, id := range query.TxIDs {
119				filter[id] = struct{}{}
120			}
121		}
122	
123		stats := TimeStats{Buckets: make([]TimeBucket, count)}
124		for i := range stats.Buckets {
125			stats.Buckets[i].Start = bucketBoundary(query.Start, query.StepSeconds, int64(i))
126			// A saturated boundary (MaxInt64) and the overshooting final step
127			// are both cut back to the requested window end.
128			end := bucketBoundary(query.Start, query.StepSeconds, int64(i)+1)
129			if end > query.End {
130				end = query.End
131			}
132			stats.Buckets[i].End = end
133		}
134	
135		index.mu.Lock()
136		defer index.mu.Unlock()
137	
138		if to == 0 || to > index.Tip {
139			to = index.Tip
140		}
141		stats.FromHeight = from
142		stats.ToHeight = to
143		if from > to {
144			// Empty index or a start above the tip: zeroed buckets are still
145			// returned for the whole requested window.
146			return stats, nil
147		}
148	
149		if statsQueryHookLocked != nil {
150			statsQueryHookLocked(to)
151		}
152	
153		distinct := make([]map[string]struct{}, count)
154		windowDistinct := make(map[string]struct{})
155		for height := from; height <= to; height++ {
156			block := index.Blocks[height]
157			if block.Time == nil {
